import { useMemo, useState } from "react";
import {
  ACTIVATION_READINESS_STAGES,
  ACTIVATION_REVIEW_DECISION_ACTIONS,
  ACTIVATION_REVIEW_LOOP,
  ACTIVATION_REVIEW_NEXT_DECISIONS,
  ACTIVATION_REVIEW_SUMMARY,
  ACTIVATION_RETURN_METRICS,
  ACTIVATION_RETURN_REVIEW,
  ACTIVATION_SUCCESS_LANGUAGE,
} from "@promorang/shared";
import { useQuery } from "@tanstack/react-query";
import { useNavigate, useParams } from "react-router-dom";
import { ArrowLeft, ArrowRight, CalendarDays, Camera, Check, CircleDollarSign, HeartHandshake, MapPin, Rocket, ShieldCheck, Sparkles, Store, Ticket, Users } from "lucide-react";

import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { useAuth } from "@/contexts/AuthContext";
import { useActivationOperations } from "@/hooks/useActivationOperations";
import { supabase } from "@/integrations/supabase/client";

type Metadata = Record<string, unknown> & { scene?: string; location?: string; outcome_detail?: string; content_needed?: string[]; collaborators?: string[]; participant_value?: string[]; social_return?: string; commercial_return?: string; what_counts?: string; funder_contribution?: string };
type MomentOption = { id: string; title: string; location: string; starts_at: string; image_url: string | null };
type OperationalActivation = { id: string; title: string; description: string | null; budget: number | null; funding_goal_gems?: number | null; status: string | null; target_moment_id: string | null; metadata: unknown; scene_id?: string | null; lifecycle_state?: string };

const stages = ACTIVATION_READINESS_STAGES.slice(0, 5);
const workspaceFocuses = [
  { id: "shape", label: "Shape", detail: "Scene, Moment + story", icon: CalendarDays },
  { id: "team", label: "Gather", detail: "People + contributions", icon: Users },
  { id: "value", label: "Fund + open", detail: "Access, Gems + promises", icon: CircleDollarSign },
  { id: "review", label: "Learn", detail: "Return + next decision", icon: Sparkles },
] as const;
type WorkspaceFocus = (typeof workspaceFocuses)[number]["id"];

export default function ActivationDetail() {
  const { id = "" } = useParams();
  const navigate = useNavigate();
  const { user } = useAuth();
  const [momentPickerOpen, setMomentPickerOpen] = useState(false);
  const [scenePickerOpen, setScenePickerOpen] = useState(false);
  const [workspaceFocus, setWorkspaceFocus] = useState<WorkspaceFocus>("shape");
  const [inviteForm, setInviteForm] = useState({ userId: "", role: "creator", responsibility: "" });
  const [contentForm, setContentForm] = useState({ phase: "before", title: "", direction: "" });
  const [contributionForm, setContributionForm] = useState({ type: "cash", description: "", amount: "" });
  const [returnForm, setReturnForm] = useState({ showed: "", returned: "", stories: "", collaborations: "", grossValue: "", human: "", commercial: "", content: "", gems: "", participantValue: "", sceneLearning: "", nextDecision: "improve", nextDecisionNote: "" });
  const [accessForm, setAccessForm] = useState({ name: "", description: "", type: "free", price: "", capacity: "", eligibility: "", reward: "" });
  const [secureAmount, setSecureAmount] = useState("");
  const [payoutForm, setPayoutForm] = useState({ collaboratorId: "", purpose: "", amount: "", condition: "" });
  const [caseForm, setCaseForm] = useState({ type: "other", title: "", description: "", resolution: "" });
  const { data: activation, isLoading } = useQuery({ queryKey: ["activation", id], queryFn: async () => { const { data, error } = await supabase.from("proposals").select("*").eq("id", id).single(); if (error) throw error; return data as OperationalActivation; }, enabled: Boolean(id) });
  const { data: moments = [] } = useQuery({ queryKey: ["activation-moment-options", user?.id], queryFn: async () => { if (!user) return []; const { data, error } = await supabase.from("moments").select("id,title,location,starts_at,image_url").eq("host_id", user.id).order("starts_at", { ascending: true }).limit(12); if (error) throw error; return (data || []) as MomentOption[]; }, enabled: Boolean(user) });
  const operations = useActivationOperations(id);
  const metadata = useMemo(() => (activation?.metadata || {}) as Metadata, [activation?.metadata]);
  const connectedMoment = moments.find((moment) => moment.id === activation?.target_moment_id);
  const readiness = useMemo(() => [Boolean(metadata.outcome_detail && (activation?.scene_id || metadata.scene)), Boolean(activation?.target_moment_id), Boolean((operations.operations.data?.content.length || metadata.content_needed?.length) && (operations.operations.data?.collaborators.length || metadata.collaborators?.length)), Boolean(metadata.participant_value?.length && metadata.social_return && metadata.commercial_return), ["funded", "live", "completed", "reviewed"].includes(activation?.lifecycle_state || "")], [activation, metadata, operations.operations.data]);
  const nextStage = readiness.findIndex((ready) => !ready);
  const recommendedFocus: WorkspaceFocus = nextStage < 0 ? "review" : nextStage <= 1 ? "shape" : nextStage === 2 ? "team" : "value";
  const myInvitation = operations.operations.data?.collaborators.find((person) => person.invited_user_id === user?.id && ["invited", "viewed", "changes_requested"].includes(person.status));
  const fundingGoal = Number(activation?.funding_goal_gems || activation?.budget || 0);
  const reserve = operations.operations.data?.reserve;
  const walletGems = Number(operations.operations.data?.wallet?.gems || 0);
  const securedGems = Number(reserve?.secured_gems || 0);
  const releasedGems = Number(reserve?.released_gems || 0);
  const refundedGems = Number(reserve?.refunded_gems || 0);
  const usableReserve = Math.max(securedGems - releasedGems - refundedGems, 0);
  const latestOutcome = operations.operations.data?.outcomes?.[0];
  const decisionAction = latestOutcome?.next_decision ? ACTIVATION_REVIEW_DECISION_ACTIONS[latestOutcome.next_decision as keyof typeof ACTIVATION_REVIEW_DECISION_ACTIONS] : null;
  const reviewLoop = ACTIVATION_REVIEW_LOOP.map((item) => {
    const value = item.id === "people" && latestOutcome
      ? `${Number(latestOutcome.people_showed_up).toLocaleString()} showed · ${Number(latestOutcome.people_returned).toLocaleString()} returned`
      : item.id === "content" && latestOutcome
        ? `${Number(latestOutcome.stories_created).toLocaleString()} stories created`
        : item.id === "content" && metadata.content_needed?.length
          ? metadata.content_needed.join(" · ")
          : item.id === "contribution" && latestOutcome
            ? `${Number(latestOutcome.collaborations_opened).toLocaleString()} doors opened`
            : item.id === "contribution" && metadata.what_counts
              ? metadata.what_counts
              : item.id === "value"
                ? `${releasedGems.toLocaleString()} Gems released · ${usableReserve.toLocaleString()} held for release`
                : item.id === "commercial" && (latestOutcome?.commercial_return_summary || metadata.commercial_return)
                  ? latestOutcome?.commercial_return_summary || metadata.commercial_return
                  : item.id === "scene" && (latestOutcome?.scene_learning_summary || latestOutcome?.human_return_summary || metadata.social_return)
                    ? latestOutcome?.scene_learning_summary || latestOutcome?.human_return_summary || metadata.social_return
                    : item.id === "next" && latestOutcome
                      ? `${latestOutcome.next_decision ? `${latestOutcome.next_decision}: ` : ""}${latestOutcome.next_decision_note || `Use this return to shape the next Moment in ${metadata.scene || "the Scene"}.`}`
                      : item.empty;
    return { ...item, value };
  });

  if (isLoading) return <main className="min-h-screen bg-[#080808] p-8 text-white"><div className="mx-auto h-96 max-w-6xl animate-pulse rounded-[2rem] bg-white/[0.04]" /></main>;
  if (!activation) return <main className="min-h-screen bg-[#080808] p-8 text-white"><p>Activation not found.</p></main>;

  return <main className="min-h-screen bg-[#080808] px-4 pb-24 pt-8 text-white sm:px-6"><div className="mx-auto max-w-6xl">
    <button onClick={() => navigate("/dashboard/proposals")} className="flex items-center gap-2 text-xs font-bold text-white/45 hover:text-white"><ArrowLeft className="h-4 w-4" />Activation Studio</button>
    <header className="mt-7 grid gap-7 border-b border-white/10 pb-8 lg:grid-cols-[1fr_310px] lg:items-end"><div><div className="flex flex-wrap items-center gap-2"><span className="rounded-full bg-primary/12 px-3 py-1 text-[9px] font-black uppercase tracking-[0.18em] text-primary">{metadata.scene || "Scene to be chosen"}</span>{metadata.location && <span className="flex items-center gap-1 text-xs text-white/40"><MapPin className="h-3 w-3" />{metadata.location}</span>}</div><h1 className="mt-4 font-serif text-4xl font-bold leading-none sm:text-6xl">{activation.title}</h1><p className="mt-4 max-w-3xl text-sm leading-6 text-white/55">{metadata.outcome_detail || activation.description}</p></div><button type="button" onClick={() => setWorkspaceFocus(recommendedFocus)} className="rounded-2xl border border-primary/25 bg-primary/10 p-5 text-left transition hover:border-primary/50 hover:bg-primary/15"><p className="text-[9px] font-black uppercase tracking-[0.18em] text-primary">Next move</p><p className="mt-2 font-serif text-2xl font-bold">{nextStage < 0 ? ACTIVATION_RETURN_REVIEW.reviewedCta : stages[nextStage].label}</p><p className="mt-2 text-xs leading-5 text-white/50">{nextStage < 0 ? ACTIVATION_RETURN_REVIEW.emptyBody : stages[nextStage].detail}</p><span className="mt-4 flex items-center gap-2 text-[9px] font-black uppercase tracking-[.15em] text-primary">Open this work <ArrowRight className="h-3.5 w-3.5" /></span></button></header>

    <section className="mt-6 grid gap-2 sm:grid-cols-5">{stages.map((stage, index) => <div key={stage.id} className={`rounded-xl border p-3 ${readiness[index] ? "border-primary/25 bg-primary/10" : index === nextStage ? "border-white/25 bg-white/[0.06]" : "border-white/8 bg-white/[0.025]"}`}><div className={`flex h-6 w-6 items-center justify-center rounded-full ${readiness[index] ? "bg-primary text-black" : "bg-white/8 text-white/35"}`}>{readiness[index] ? <Check className="h-3.5 w-3.5" /> : <span className="text-[9px] font-bold">{index + 1}</span>}</div><p className="mt-3 text-[9px] font-black uppercase tracking-[0.12em] text-white/65">{stage.label}</p><p className="mt-2 text-[10px] leading-4 text-white/35">{readiness[index] ? stage.completeMeaning : stage.detail}</p></div>)}</section>
    {myInvitation && <section className="mt-5 rounded-[2rem] border border-primary/30 bg-primary/10 p-6"><p className="text-[9px] font-black uppercase tracking-[0.18em] text-primary">You have been invited as {myInvitation.role.replaceAll("_", " ")}</p><h2 className="mt-2 font-serif text-2xl font-bold">{myInvitation.responsibility || "Help bring this activation alive."}</h2><div className="mt-5 flex flex-wrap gap-2"><Button onClick={() => operations.respond.mutate({ collaboratorId: myInvitation.id, response: "accepted" })} className="bg-primary font-black text-black">I’m in</Button><Button onClick={() => operations.respond.mutate({ collaboratorId: myInvitation.id, response: "changes_requested", message: "I would like to align on the responsibility before accepting." })} variant="outline" className="border-white/15 bg-transparent text-white">Let’s align first</Button><Button onClick={() => operations.respond.mutate({ collaboratorId: myInvitation.id, response: "declined" })} variant="ghost" className="text-white/50">Not this time</Button></div></section>}

    <nav className="mt-6 grid gap-2 rounded-[2rem] border border-white/10 bg-[#10100f] p-2 sm:grid-cols-4" aria-label="Activation workspace focus">
      {workspaceFocuses.map(({ id: focusId, label, detail, icon: Icon }) => <button key={focusId} type="button" aria-current={workspaceFocus === focusId ? "step" : undefined} onClick={() => setWorkspaceFocus(focusId)} className={`group flex items-center gap-3 rounded-[1.35rem] border p-4 text-left transition ${workspaceFocus === focusId ? "border-primary/30 bg-primary text-black" : "border-transparent bg-transparent text-white hover:border-white/10 hover:bg-white/[.04]"}`}><span className={`flex h-9 w-9 shrink-0 items-center justify-center rounded-xl ${workspaceFocus === focusId ? "bg-black/10" : "bg-primary/10 text-primary"}`}><Icon className="h-4 w-4" /></span><span><strong className="block text-xs">{label}</strong><small className={`mt-1 block text-[9px] ${workspaceFocus === focusId ? "text-black/60" : "text-white/35"}`}>{detail}</small></span></button>)}
    </nav>

    <section className="mt-6 grid gap-5 lg:grid-cols-[1fr_340px]">
      <div className="space-y-5">
        {workspaceFocus === "shape" && <>
        <Panel eyebrow="Scene + Moment" title="Give the Scene a reason to gather now" icon={CalendarDays}>
          <p className="text-sm leading-6 text-white/50">The Scene carries the relationships. The Moment is where people meet, participate, create, and contribute.</p>
          <div className="mt-5 grid gap-3 sm:grid-cols-2">
            <button onClick={() => setScenePickerOpen(!scenePickerOpen)} className={`rounded-2xl border p-4 text-left ${activation.scene_id ? "border-primary/25 bg-primary/10" : "border-white/10 bg-black/30"}`}><p className="text-[8px] font-black uppercase tracking-[0.15em] text-primary">Scene</p><p className="mt-1 font-bold">{operations.scenes.data?.find((scene) => scene.id === activation.scene_id)?.title || metadata.scene || "Choose a real Scene"}</p></button>
            <button onClick={() => setMomentPickerOpen(!momentPickerOpen)} className={`rounded-2xl border p-4 text-left ${connectedMoment ? "border-primary/25 bg-primary/10" : "border-white/10 bg-black/30"}`}><p className="text-[8px] font-black uppercase tracking-[0.15em] text-primary">Moment</p><p className="mt-1 font-bold">{connectedMoment?.title || "Choose a Moment you host"}</p></button>
          </div>
          {scenePickerOpen && <div className="mt-3 grid gap-2">{operations.scenes.data?.map((scene) => <button key={scene.id} onClick={() => { operations.linkScene.mutate(scene.id); setScenePickerOpen(false); }} className="flex items-center justify-between rounded-xl border border-white/10 bg-black/30 p-4 text-left hover:border-primary/50"><span><strong className="block text-sm">{scene.title}</strong><small className="mt-1 block text-white/40">{scene.city || scene.description || "A Promorang Scene"}</small></span><ArrowRight className="h-4 w-4 text-primary" /></button>)}</div>}
          {momentPickerOpen && <div className="mt-3 grid gap-2">{moments.length ? moments.map((moment) => <button key={moment.id} onClick={() => { operations.linkMoment.mutate(moment.id); setMomentPickerOpen(false); }} className="flex items-center justify-between rounded-xl border border-white/10 bg-black/30 p-4 text-left hover:border-primary/50"><span><strong className="block text-sm">{moment.title}</strong><small className="mt-1 block text-white/40">{moment.location} · {new Date(moment.starts_at).toLocaleDateString()}</small></span><ArrowRight className="h-4 w-4 text-primary" /></button>) : <p className="rounded-xl border border-white/10 p-4 text-sm text-white/45">Create a Moment first; only Moments you host can be connected.</p>}</div>}
        </Panel>
        <Panel eyebrow="Content direction" title="Build the story before, during, and after" icon={Camera}><RoleGrid values={metadata.content_needed} empty="No content roles chosen yet." /><p className="mt-5 text-xs leading-5 text-white/45">Content is not an attachment to the Moment. It creates desire before people arrive, helps them participate while there, and carries the Scene into what comes next.</p></Panel>
        </>}
        {workspaceFocus === "team" && <>
        <Panel eyebrow="The human network" title="Put the right people around the experience" icon={Users}>
          <div className="grid gap-2">{operations.operations.data?.collaborators.map((person) => <div key={person.id} className="flex items-center justify-between rounded-xl border border-white/10 bg-black/25 p-4"><div><p className="text-sm font-bold">{person.display_name || "Invited collaborator"}</p><p className="mt-1 text-[10px] capitalize text-white/40">{person.role} · {person.responsibility || "Contribution to be agreed"}</p></div><span className={`rounded-full px-2.5 py-1 text-[8px] font-black uppercase ${person.status === "accepted" ? "bg-emerald-500/15 text-emerald-400" : "bg-primary/10 text-primary"}`}>{person.status.replaceAll("_", " ")}</span></div>)}</div>
          <div className="mt-5 grid gap-3 rounded-2xl border border-white/10 bg-black/25 p-4 sm:grid-cols-2">
            <select value={inviteForm.userId} onChange={(event) => setInviteForm((current) => ({ ...current, userId: event.target.value }))} className="h-10 rounded-md border border-white/10 bg-black px-3 text-xs text-white"><option value="">Choose a person</option>{operations.people.data?.map((person) => <option key={person.user_id} value={person.user_id}>{person.full_name}</option>)}</select>
            <select value={inviteForm.role} onChange={(event) => setInviteForm((current) => ({ ...current, role: event.target.value }))} className="h-10 rounded-md border border-white/10 bg-black px-3 text-xs text-white">{["host", "creator", "venue", "merchant", "brand", "agency", "scene_lead", "supporter"].map((role) => <option key={role} value={role}>{role.replaceAll("_", " ")}</option>)}</select>
            <Input value={inviteForm.responsibility} onChange={(event) => setInviteForm((current) => ({ ...current, responsibility: event.target.value }))} placeholder="What are they being invited to make possible?" className="border-white/10 bg-black text-white sm:col-span-2" />
            <Button disabled={!inviteForm.userId || !inviteForm.responsibility.trim()} onClick={() => { const person = operations.people.data?.find((item) => item.user_id === inviteForm.userId); if (person) operations.invite.mutate({ userId: person.user_id, name: person.full_name || "Collaborator", role: inviteForm.role, responsibility: inviteForm.responsibility }); }} className="bg-primary font-black text-black sm:col-span-2">Open invitation</Button>
          </div>
        </Panel>
        <Panel eyebrow="Story responsibilities" title="Turn content direction into owned work" icon={Camera}>
          <div className="grid gap-2">{operations.operations.data?.content.map((item) => <div key={item.id} className="rounded-xl border border-white/10 bg-black/25 p-4"><div className="flex items-center justify-between"><p className="font-bold">{item.title}</p><span className="text-[8px] font-black uppercase text-primary">{item.phase} · {item.status}</span></div><p className="mt-2 text-xs leading-5 text-white/45">{item.direction}</p></div>)}</div>
          <div className="mt-5 grid gap-3 rounded-2xl border border-white/10 bg-black/25 p-4"><select value={contentForm.phase} onChange={(event) => setContentForm((current) => ({ ...current, phase: event.target.value }))} className="h-10 rounded-md border border-white/10 bg-black px-3 text-xs text-white">{["invite", "before", "live", "after", "evergreen"].map((phase) => <option key={phase}>{phase}</option>)}</select><Input value={contentForm.title} onChange={(event) => setContentForm((current) => ({ ...current, title: event.target.value }))} placeholder="Responsibility title" className="border-white/10 bg-black text-white" /><Textarea value={contentForm.direction} onChange={(event) => setContentForm((current) => ({ ...current, direction: event.target.value }))} placeholder="What should this content help people feel, understand, or do?" className="border-white/10 bg-black text-white" /><Button disabled={!contentForm.title.trim() || !contentForm.direction.trim()} onClick={() => operations.addContent.mutate(contentForm)} className="bg-primary font-black text-black">Add story responsibility</Button></div>
        </Panel>
        <Panel eyebrow="Contributions" title="Show what each partner is putting into the room" icon={CircleDollarSign}>
          <div className="grid gap-2">{operations.operations.data?.contributions.map((item) => <div key={item.id} className="flex items-center justify-between rounded-xl border border-white/10 bg-black/25 p-4"><div><p className="text-sm font-bold capitalize">{item.contribution_type}</p><p className="mt-1 text-xs text-white/45">{item.description}</p></div><p className="text-xs font-black text-primary">{item.amount ? `${item.currency} ${Number(item.amount).toLocaleString()}` : item.status}</p></div>)}</div>
          <div className="mt-5 grid gap-3 rounded-2xl border border-white/10 bg-black/25 p-4 sm:grid-cols-2"><select value={contributionForm.type} onChange={(event) => setContributionForm((current) => ({ ...current, type: event.target.value }))} className="h-10 rounded-md border border-white/10 bg-black px-3 text-xs text-white">{["cash", "venue", "product", "service", "access", "media", "talent", "reward", "transport", "other"].map((type) => <option key={type}>{type}</option>)}</select><Input type="number" value={contributionForm.amount} onChange={(event) => setContributionForm((current) => ({ ...current, amount: event.target.value }))} placeholder="Value, if monetary" className="border-white/10 bg-black text-white" /><Input value={contributionForm.description} onChange={(event) => setContributionForm((current) => ({ ...current, description: event.target.value }))} placeholder="What is being contributed?" className="border-white/10 bg-black text-white sm:col-span-2" /><Button disabled={!contributionForm.description.trim()} onClick={() => operations.addContribution.mutate({ type: contributionForm.type, description: contributionForm.description, amount: Number(contributionForm.amount) || undefined })} className="bg-primary font-black text-black sm:col-span-2">Record contribution</Button></div>
        </Panel>
        </>}
        {workspaceFocus === "value" && <>
        <Panel eyebrow="Access + value" title="Give people a clear way into the Moment" icon={Ticket}>
          <div className="grid gap-3 sm:grid-cols-2">{operations.operations.data?.access.map((tier) => { const myPass = operations.operations.data?.passes.find((pass) => pass.tier_id === tier.id); const canBuy = walletGems >= Number(tier.price || 0); return <div key={tier.id} className="rounded-2xl border border-white/10 bg-black/25 p-5"><div className="flex items-start justify-between"><div><p className="text-[8px] font-black uppercase tracking-[0.15em] text-primary">{tier.access_type} access</p><h3 className="mt-1 font-serif text-2xl font-bold">{tier.name}</h3></div><span className="text-xs font-black">{tier.price ? `${Number(tier.price).toLocaleString()} Gems` : "Free"}</span></div><p className="mt-3 text-xs leading-5 text-white/45">{tier.description}</p><p className="mt-3 text-[9px] text-white/35">{tier.capacity ? `${tier.issued_count} of ${tier.capacity} claimed` : `${tier.issued_count} claimed`} · {tier.eligibility_summary || "Open eligibility"}</p>{tier.price > 0 && <p className="mt-1 text-[8px] text-white/30">US${Number(tier.price).toLocaleString()} platform value</p>}{tier.reward_summary && <p className="mt-2 text-[9px] font-bold text-primary">Opens: {tier.reward_summary}</p>}{myPass ? <div className="mt-4 rounded-xl bg-primary p-3 text-black"><p className="text-[8px] font-black uppercase">Your access</p><p className="mt-1 font-mono text-xs">{myPass.pass_code}</p></div> : tier.access_type === "free" && tier.status === "open" ? <Button onClick={() => operations.claimAccess.mutate(tier.id)} className="mt-4 w-full bg-primary font-black text-black">Claim access</Button> : tier.access_type === "paid" ? canBuy ? <Button disabled={operations.purchaseAccess.isPending || tier.status !== "open"} onClick={() => operations.purchaseAccess.mutate(tier.id)} className="mt-4 w-full justify-between bg-primary font-black text-black">Use Gems for access <ArrowRight className="h-4 w-4" /></Button> : <Button onClick={() => navigate("/wallet")} className="mt-4 w-full justify-between bg-primary font-black text-black">Need more Gems <ArrowRight className="h-4 w-4" /></Button> : null}</div>; })}</div>
          <div className="mt-5 grid gap-3 rounded-2xl border border-white/10 bg-black/25 p-4 sm:grid-cols-2"><Input value={accessForm.name} onChange={(event) => setAccessForm((current) => ({ ...current, name: event.target.value }))} placeholder="Access name" className="border-white/10 bg-black text-white" /><select value={accessForm.type} onChange={(event) => setAccessForm((current) => ({ ...current, type: event.target.value, price: event.target.value === "paid" ? current.price : "" }))} className="h-10 rounded-md border border-white/10 bg-black px-3 text-xs text-white">{["free", "paid", "invite", "earned", "reward", "draw"].map((type) => <option key={type}>{type}</option>)}</select><Input type="number" value={accessForm.price} disabled={accessForm.type !== "paid"} onChange={(event) => setAccessForm((current) => ({ ...current, price: event.target.value }))} placeholder="Price in Gems" className="border-white/10 bg-black text-white" /><Input type="number" value={accessForm.capacity} onChange={(event) => setAccessForm((current) => ({ ...current, capacity: event.target.value }))} placeholder="Capacity" className="border-white/10 bg-black text-white" /><Textarea value={accessForm.description} onChange={(event) => setAccessForm((current) => ({ ...current, description: event.target.value }))} placeholder="What kind of experience or access is this?" className="border-white/10 bg-black text-white sm:col-span-2" /><Input value={accessForm.eligibility} onChange={(event) => setAccessForm((current) => ({ ...current, eligibility: event.target.value }))} placeholder="Who is this for?" className="border-white/10 bg-black text-white" /><Input value={accessForm.reward} onChange={(event) => setAccessForm((current) => ({ ...current, reward: event.target.value }))} placeholder="What else can it open?" className="border-white/10 bg-black text-white" /><Button disabled={!activation.target_moment_id || !accessForm.name.trim() || (accessForm.type === "paid" && !Number(accessForm.price))} onClick={() => operations.addAccess.mutate({ momentId: activation.target_moment_id || undefined, name: accessForm.name, description: accessForm.description, type: accessForm.type, price: Number(accessForm.price) || 0, capacity: Number(accessForm.capacity) || undefined, eligibility: accessForm.eligibility, reward: accessForm.reward })} className="bg-primary font-black text-black sm:col-span-2">Open this access path</Button></div>
        </Panel>
        <Panel eyebrow="Payout promises" title="Make compensation visible before the work" icon={CircleDollarSign}>
          <div className="grid gap-2">{operations.operations.data?.payouts.map((payout) => <div key={payout.id} className="flex items-center justify-between rounded-xl border border-white/10 bg-black/25 p-4"><div><p className="text-sm font-bold">{payout.purpose}</p><p className="mt-1 text-[9px] text-white/40">Released when: {payout.release_condition}</p></div><div className="text-right"><p className="text-sm font-black text-primary">{Number(payout.amount).toLocaleString()} Gems</p><p className="mt-1 text-[8px] uppercase text-white/35">{payout.status}</p>{payout.status === "earned" && <button disabled={operations.releasePayout.isPending || usableReserve < Number(payout.amount)} onClick={() => operations.releasePayout.mutate(payout.id)} className="mt-2 text-[9px] font-black text-primary disabled:text-white/25">Release Gems</button>}</div></div>)}</div>
          <div className="mt-5 grid gap-3 rounded-2xl border border-white/10 bg-black/25 p-4 sm:grid-cols-2"><select value={payoutForm.collaboratorId} onChange={(event) => setPayoutForm((current) => ({ ...current, collaboratorId: event.target.value }))} className="h-10 rounded-md border border-white/10 bg-black px-3 text-xs text-white"><option value="">Choose an accepted collaborator</option>{operations.operations.data?.collaborators.filter((person) => person.status === "accepted" && person.invited_user_id).map((person) => <option key={person.id} value={person.id}>{person.display_name} · {person.role}</option>)}</select><Input type="number" value={payoutForm.amount} onChange={(event) => setPayoutForm((current) => ({ ...current, amount: event.target.value }))} placeholder="Amount in Gems" className="border-white/10 bg-black text-white" /><Input value={payoutForm.purpose} onChange={(event) => setPayoutForm((current) => ({ ...current, purpose: event.target.value }))} placeholder="What is this Gem payment for?" className="border-white/10 bg-black text-white sm:col-span-2" /><Input value={payoutForm.condition} onChange={(event) => setPayoutForm((current) => ({ ...current, condition: event.target.value }))} placeholder="What must be completed before release?" className="border-white/10 bg-black text-white sm:col-span-2" /><Button disabled={!payoutForm.collaboratorId || !payoutForm.purpose.trim() || !Number(payoutForm.amount) || !payoutForm.condition.trim()} onClick={() => { const collaborator = operations.operations.data?.collaborators.find((person) => person.id === payoutForm.collaboratorId); if (collaborator?.invited_user_id) operations.addPayout.mutate({ momentId: activation.target_moment_id || undefined, collaboratorId: collaborator.id, recipientId: collaborator.invited_user_id, purpose: payoutForm.purpose, amount: Number(payoutForm.amount), condition: payoutForm.condition }); }} className="bg-primary font-black text-black sm:col-span-2">Record Gem payout promise</Button></div>
        </Panel>
        <Panel eyebrow="Help + resolution" title="Make problems visible before trust is lost" icon={ShieldCheck}>
          <div className="flex flex-wrap gap-2">{operations.operations.data?.cases.map((item) => <span key={item.id} className="rounded-full border border-white/10 bg-black/25 px-3 py-2 text-[9px] font-bold">{item.title} · <span className="text-primary">{item.status}</span></span>)}</div>
          <div className="mt-5 grid gap-3 rounded-2xl border border-white/10 bg-black/25 p-4 sm:grid-cols-2"><select value={caseForm.type} onChange={(event) => setCaseForm((current) => ({ ...current, type: event.target.value }))} className="h-10 rounded-md border border-white/10 bg-black px-3 text-xs text-white">{["cancellation", "refund", "access", "contribution", "content", "payout", "safety", "other"].map((type) => <option key={type}>{type}</option>)}</select><Input value={caseForm.title} onChange={(event) => setCaseForm((current) => ({ ...current, title: event.target.value }))} placeholder="What needs attention?" className="border-white/10 bg-black text-white" /><Textarea value={caseForm.description} onChange={(event) => setCaseForm((current) => ({ ...current, description: event.target.value }))} placeholder="Explain what happened in plain language." className="border-white/10 bg-black text-white sm:col-span-2" /><Input value={caseForm.resolution} onChange={(event) => setCaseForm((current) => ({ ...current, resolution: event.target.value }))} placeholder="What would make this right?" className="border-white/10 bg-black text-white sm:col-span-2" /><Button disabled={!caseForm.title.trim() || !caseForm.description.trim()} onClick={() => operations.openCase.mutate({ momentId: activation.target_moment_id || undefined, type: caseForm.type, title: caseForm.title, description: caseForm.description, resolution: caseForm.resolution })} variant="outline" className="border-white/15 bg-transparent text-white sm:col-span-2">Ask for help</Button></div>
        </Panel>
        </>}
        {workspaceFocus === "review" && <>
        <Panel eyebrow="Shared return" title="Make the experience valuable from every side" icon={HeartHandshake}><div className="grid gap-4 sm:grid-cols-2"><Return title="For participants" value={metadata.social_return || metadata.participant_value?.join(" · ")} /><Return title="For venues, merchants + brands" value={metadata.commercial_return} /></div><p className="mt-4 text-xs leading-5 text-white/40">{ACTIVATION_SUCCESS_LANGUAGE.sharedReturn}</p></Panel>
        <Panel eyebrow={ACTIVATION_RETURN_REVIEW.eyebrow} title={ACTIVATION_RETURN_REVIEW.title} icon={Sparkles}>
          <div className="mb-4 rounded-2xl border border-primary/20 bg-primary/[0.06] p-5">
            <p className="text-[9px] font-black uppercase tracking-[0.18em] text-primary">{ACTIVATION_REVIEW_SUMMARY.title}</p>
            <p className="mt-2 text-sm leading-6 text-white/55">{ACTIVATION_REVIEW_SUMMARY.body}</p>
            <div className="mt-4 grid gap-3 md:grid-cols-2 xl:grid-cols-3">{reviewLoop.map((item) => <ReviewLoopCard key={item.id} label={item.label} question={item.question} value={item.value} signal={item.signal} />)}</div>
          </div>
          {latestOutcome && <ActivationReviewReport outcome={latestOutcome} decisionAction={decisionAction} sceneName={metadata.scene || "this Scene"} onRepeat={() => navigate("/propose/new")} onInvite={() => setWorkspaceFocus("team")} onFund={() => setWorkspaceFocus("value")} />}
          {operations.operations.data?.outcomes.map((outcome) => <div key={outcome.id} className="mb-4 rounded-2xl border border-primary/20 bg-primary/[0.07] p-5"><div className="grid grid-cols-2 gap-3 sm:grid-cols-5"><Result value={outcome.people_showed_up} label="Showed up" /><Result value={outcome.people_returned} label="Returned" /><Result value={outcome.stories_created} label="Stories" /><Result value={outcome.collaborations_opened} label="Doors opened" /><Result value={`${outcome.currency} ${Number(outcome.gross_value).toLocaleString()}`} label="Value moved" /></div><p className="mt-5 text-sm leading-6 text-white/65">{outcome.human_return_summary}</p><p className="mt-2 text-xs leading-5 text-white/40">{outcome.commercial_return_summary}</p>{outcome.content_return_summary && <p className="mt-3 text-xs leading-5 text-white/45">Content: {outcome.content_return_summary}</p>}{outcome.gems_return_summary && <p className="mt-2 text-xs leading-5 text-white/45">Gems: {outcome.gems_return_summary}</p>}{outcome.scene_learning_summary && <p className="mt-2 text-xs leading-5 text-white/45">Scene learning: {outcome.scene_learning_summary}</p>}{outcome.next_decision && <p className="mt-3 rounded-full border border-primary/20 bg-black/25 px-3 py-2 text-[9px] font-black uppercase tracking-[0.14em] text-primary">Next decision: {outcome.next_decision}{outcome.next_decision_note ? ` · ${outcome.next_decision_note}` : ""}</p>}</div>)}
          {!operations.operations.data?.outcomes.length && <div className="mb-4 rounded-2xl border border-white/10 bg-black/25 p-5"><p className="font-serif text-2xl font-bold">{ACTIVATION_RETURN_REVIEW.emptyTitle}</p><p className="mt-2 text-sm leading-6 text-white/45">{ACTIVATION_RETURN_REVIEW.emptyBody}</p></div>}
          {["completed", "reviewed"].includes(activation.lifecycle_state || "") && <div className="grid gap-3 rounded-2xl border border-white/10 bg-black/25 p-4 sm:grid-cols-2"><Input type="number" value={returnForm.showed} onChange={(event) => setReturnForm((current) => ({ ...current, showed: event.target.value }))} placeholder={ACTIVATION_RETURN_METRICS[0].prompt} className="border-white/10 bg-black text-white" /><Input type="number" value={returnForm.returned} onChange={(event) => setReturnForm((current) => ({ ...current, returned: event.target.value }))} placeholder={ACTIVATION_RETURN_METRICS[1].prompt} className="border-white/10 bg-black text-white" /><Input type="number" value={returnForm.stories} onChange={(event) => setReturnForm((current) => ({ ...current, stories: event.target.value }))} placeholder={ACTIVATION_RETURN_METRICS[2].prompt} className="border-white/10 bg-black text-white" /><Input type="number" value={returnForm.collaborations} onChange={(event) => setReturnForm((current) => ({ ...current, collaborations: event.target.value }))} placeholder={ACTIVATION_RETURN_METRICS[3].prompt} className="border-white/10 bg-black text-white" /><Input type="number" value={returnForm.grossValue} onChange={(event) => setReturnForm((current) => ({ ...current, grossValue: event.target.value }))} placeholder={ACTIVATION_RETURN_METRICS[4].prompt} className="border-white/10 bg-black text-white sm:col-span-2" /><Textarea value={returnForm.human} onChange={(event) => setReturnForm((current) => ({ ...current, human: event.target.value }))} placeholder={ACTIVATION_RETURN_REVIEW.participantPrompt} className="border-white/10 bg-black text-white sm:col-span-2" /><Textarea value={returnForm.commercial} onChange={(event) => setReturnForm((current) => ({ ...current, commercial: event.target.value }))} placeholder={ACTIVATION_RETURN_REVIEW.commercialPrompt} className="border-white/10 bg-black text-white sm:col-span-2" /><Textarea value={returnForm.content} onChange={(event) => setReturnForm((current) => ({ ...current, content: event.target.value }))} placeholder="What content was created, shared, saved, or made useful?" className="border-white/10 bg-black text-white sm:col-span-2" /><Textarea value={returnForm.gems} onChange={(event) => setReturnForm((current) => ({ ...current, gems: event.target.value }))} placeholder="What Gems were secured, released, earned, refunded, or held?" className="border-white/10 bg-black text-white sm:col-span-2" /><Textarea value={returnForm.participantValue} onChange={(event) => setReturnForm((current) => ({ ...current, participantValue: event.target.value }))} placeholder="What participant value opened: access, memory, reward, invitation, opportunity?" className="border-white/10 bg-black text-white sm:col-span-2" /><Textarea value={returnForm.sceneLearning} onChange={(event) => setReturnForm((current) => ({ ...current, sceneLearning: event.target.value }))} placeholder="What did the Scene learn about people, rituals, places, creators, or partners?" className="border-white/10 bg-black text-white sm:col-span-2" /><select value={returnForm.nextDecision} onChange={(event) => setReturnForm((current) => ({ ...current, nextDecision: event.target.value }))} className="h-10 rounded-md border border-white/10 bg-black px-3 text-xs text-white">{ACTIVATION_REVIEW_NEXT_DECISIONS.map((decision) => <option key={decision.id} value={decision.id}>{decision.label} — {decision.meaning}</option>)}</select><Input value={returnForm.nextDecisionNote} onChange={(event) => setReturnForm((current) => ({ ...current, nextDecisionNote: event.target.value }))} placeholder="Why is this the next move?" className="border-white/10 bg-black text-white" /><Button disabled={!returnForm.human.trim() || !returnForm.commercial.trim()} onClick={() => operations.recordOutcome.mutate({ sceneId: activation.scene_id || undefined, momentId: activation.target_moment_id || undefined, showed: Number(returnForm.showed) || 0, returned: Number(returnForm.returned) || 0, stories: Number(returnForm.stories) || 0, collaborations: Number(returnForm.collaborations) || 0, grossValue: Number(returnForm.grossValue) || 0, human: returnForm.human, commercial: returnForm.commercial, content: returnForm.content, gems: returnForm.gems, participantValue: returnForm.participantValue, sceneLearning: returnForm.sceneLearning, nextDecision: returnForm.nextDecision, nextDecisionNote: returnForm.nextDecisionNote, reviewLoop: { people: `${returnForm.showed || 0} showed · ${returnForm.returned || 0} returned`, content: returnForm.content, contribution: `${returnForm.collaborations || 0} doors opened`, value: returnForm.gems, commercial: returnForm.commercial, scene: returnForm.sceneLearning, next: returnForm.nextDecisionNote } })} className="bg-primary font-black text-black sm:col-span-2">{ACTIVATION_RETURN_REVIEW.recordCta}</Button></div>}
        </Panel>
        </>}
      </div>
      <aside className="space-y-5 lg:sticky lg:top-6 lg:self-start"><div className="rounded-[2rem] border border-white/10 bg-[#111110] p-6"><p className="text-[9px] font-black uppercase tracking-[0.18em] text-white/35">Bring it alive</p><p className="mt-2 font-serif text-2xl font-bold capitalize">{(activation.lifecycle_state || "shaping").replaceAll("_", " ")}</p><div className="mt-5 space-y-4"><Info icon={CircleDollarSign} label="Your Gem wallet" value={`${walletGems.toLocaleString()} Gems available`} /><Info icon={CircleDollarSign} label="Gem funding goal" value={fundingGoal ? `${fundingGoal.toLocaleString()} Gems · US$${fundingGoal.toLocaleString()} value` : "To be agreed"} /><Info icon={ShieldCheck} label="Gems secured" value={`${securedGems.toLocaleString()} Gems`} /><Info icon={ShieldCheck} label="Still held for release" value={`${usableReserve.toLocaleString()} Gems`} /><Info icon={Store} label="Partner contribution" value={metadata.funder_contribution || "Gems, place, product, access, or reach"} /><Info icon={Sparkles} label="What counts" value={metadata.what_counts || "People join, contribute, return, and open what comes next."} /></div>{["aligned", "funding", "funded"].includes(activation.lifecycle_state || "") && <div className="mt-5 rounded-2xl border border-white/10 bg-black/25 p-4"><p className="text-[9px] font-black uppercase tracking-[0.14em] text-primary">Secure Gems</p><div className="mt-3 flex gap-2"><Input type="number" min="1" value={secureAmount} onChange={(event) => setSecureAmount(event.target.value)} placeholder="Amount" className="border-white/10 bg-black text-white" /><Button disabled={!Number(secureAmount) || Number(secureAmount) > walletGems || operations.secureGems.isPending} onClick={() => operations.secureGems.mutate(Number(secureAmount), { onSuccess: () => setSecureAmount("") })} className="bg-primary font-black text-black">Secure</Button></div><p className="mt-2 text-[9px] leading-4 text-white/35">1 Gem = US$1. Secured Gems are held for this activation until they are released or refunded.</p></div>}{operations.operations.data?.reservations.length ? <div className="mt-5 space-y-2"><p className="text-[9px] font-black uppercase tracking-[0.14em] text-white/35">Gem reservations</p>{operations.operations.data.reservations.slice(0, 4).map((reservation) => <div key={reservation.id} className="rounded-xl border border-white/10 bg-black/25 p-3"><div className="flex items-center justify-between gap-3"><div><p className="text-xs font-black">{Number(reservation.amount_gems).toLocaleString()} Gems</p><p className="mt-1 text-[8px] uppercase text-white/35">{reservation.purpose.replaceAll("_", " ")} · {reservation.status}</p></div>{["secured", "partially_released", "partially_refunded", "disputed"].includes(reservation.status) && <button disabled={operations.refundReservation.isPending} onClick={() => operations.refundReservation.mutate(reservation.id)} className="text-[9px] font-black text-primary">Refund</button>}</div></div>)}</div> : null}<LifecycleAction state={activation.lifecycle_state || "shaping"} ready={readiness.slice(0, 4).every(Boolean)} fundingReady={!fundingGoal || securedGems >= fundingGoal} pending={operations.move.isPending} onMove={(state) => operations.move.mutate({ state })} /></div></aside>
    </section>
  </div></main>;
}

function Panel({ eyebrow, title, icon: Icon, children }: { eyebrow: string; title: string; icon: typeof Camera; children: React.ReactNode }) { return <section className="rounded-[2rem] border border-white/10 bg-[#111110] p-6 sm:p-8"><div className="flex gap-4"><div className="flex h-11 w-11 shrink-0 items-center justify-center rounded-2xl bg-primary/12"><Icon className="h-5 w-5 text-primary" /></div><div><p className="text-[9px] font-black uppercase tracking-[0.18em] text-primary">{eyebrow}</p><h2 className="mt-1 font-serif text-2xl font-bold sm:text-3xl">{title}</h2></div></div><div className="mt-6">{children}</div></section>; }
function RoleGrid({ values = [], empty }: { values?: string[]; empty: string }) { return values.length ? <div className="flex flex-wrap gap-2">{values.map((value) => <span key={value} className="rounded-full border border-white/10 bg-black/30 px-4 py-2 text-xs font-bold capitalize text-white/70">{value.replaceAll("_", " ")}</span>)}</div> : <p className="text-sm text-white/35">{empty}</p>; }
function Return({ title, value }: { title: string; value?: string }) { return <div className="rounded-2xl border border-white/10 bg-black/25 p-5"><p className="text-[9px] font-black uppercase tracking-[0.16em] text-primary">{title}</p><p className="mt-3 text-sm leading-6 text-white/55">{value || "Define what this successful experience should open."}</p></div>; }
function Result({ value, label }: { value: string | number; label: string }) { return <div><p className="font-serif text-2xl font-bold">{value}</p><p className="mt-1 text-[8px] font-black uppercase tracking-[0.12em] text-white/35">{label}</p></div>; }
function ReviewLoopCard({ label, question, value, signal }: { label: string; question: string; value?: string; signal: string }) { return <div className="rounded-2xl border border-white/10 bg-black/30 p-4"><p className="text-[8px] font-black uppercase tracking-[0.16em] text-primary">{label}</p><p className="mt-2 text-xs font-bold leading-5 text-white/75">{question}</p><p className="mt-3 text-sm leading-5 text-white">{value}</p><p className="mt-3 text-[10px] leading-4 text-white/35">{signal}</p></div>; }
function ActivationReviewReport({ outcome, decisionAction, sceneName, onRepeat, onInvite, onFund }: { outcome: OutcomeSnapshot; decisionAction: { title: string; detail: string; cta: string } | null; sceneName: string; onRepeat: () => void; onInvite: () => void; onFund: () => void }) {
  const action = outcome.next_decision === "repeat" ? onRepeat : outcome.next_decision === "invite" ? onInvite : outcome.next_decision === "fund" ? onFund : undefined;
  return <section className="mb-4 overflow-hidden rounded-[2rem] border border-primary/25 bg-[radial-gradient(circle_at_top_right,rgba(255,106,26,0.18),transparent_34%),#0d0d0c] p-5 sm:p-6">
    <div className="grid gap-5 lg:grid-cols-[0.9fr_1.1fr]">
      <div>
        <p className="text-[9px] font-black uppercase tracking-[0.2em] text-primary">Activation review report</p>
        <h3 className="mt-2 font-serif text-3xl font-bold leading-tight">What happened, what it meant, and what {sceneName} should do next.</h3>
        <p className="mt-3 text-sm leading-6 text-white/55">{outcome.human_return_summary || "The human return still needs to be written in plain language."}</p>
        <p className="mt-2 text-xs leading-5 text-white/40">{outcome.commercial_return_summary || "The commercial return still needs to be connected to visits, sales, redemptions, demand, or partner value."}</p>
      </div>
      <div className="grid gap-2 sm:grid-cols-2">
        <ReportSignal label="People" value={`${Number(outcome.people_showed_up || 0).toLocaleString()} showed · ${Number(outcome.people_returned || 0).toLocaleString()} returned`} />
        <ReportSignal label="Content" value={outcome.content_return_summary || `${Number(outcome.stories_created || 0).toLocaleString()} stories created`} />
        <ReportSignal label="Contribution" value={`${Number(outcome.collaborations_opened || 0).toLocaleString()} doors opened`} />
        <ReportSignal label="Value" value={outcome.gems_return_summary || `${outcome.currency} ${Number(outcome.gross_value || 0).toLocaleString()} moved`} />
        <ReportSignal label="Participant value" value={outcome.participant_value_summary || "Access, memory, reward, invitation, or opportunity should be named."} />
        <ReportSignal label="Scene learning" value={outcome.scene_learning_summary || "Capture what should repeat, improve, retire, or invite next."} />
      </div>
    </div>
    <div className="mt-5 rounded-2xl border border-white/10 bg-black/30 p-4">
      <div className="flex flex-col gap-4 sm:flex-row sm:items-center sm:justify-between">
        <div>
          <p className="text-[9px] font-black uppercase tracking-[0.18em] text-primary">Decision action</p>
          <p className="mt-1 font-serif text-2xl font-bold">{decisionAction?.title || "Choose the next move"}</p>
          <p className="mt-2 text-xs leading-5 text-white/45">{outcome.next_decision_note || decisionAction?.detail || "Use the review to decide whether to repeat, improve, invite, fund, or close."}</p>
        </div>
        {decisionAction && <Button onClick={action} variant="outline" className="border-primary/30 bg-primary/10 font-black text-primary hover:bg-primary hover:text-black">{decisionAction.cta}</Button>}
      </div>
    </div>
  </section>;
}
function ReportSignal({ label, value }: { label: string; value: string }) { return <div className="rounded-2xl border border-white/10 bg-black/25 p-4"><p className="text-[8px] font-black uppercase tracking-[0.15em] text-white/35">{label}</p><p className="mt-2 text-xs leading-5 text-white/65">{value}</p></div>; }
function Info({ icon: Icon, label, value }: { icon: typeof Store; label: string; value: string }) { return <div className="flex gap-3 border-b border-white/8 pb-4"><Icon className="mt-0.5 h-4 w-4 shrink-0 text-primary" /><div><p className="text-[8px] font-black uppercase tracking-[0.14em] text-white/30">{label}</p><p className="mt-1 text-xs leading-5 text-white/65">{value}</p></div></div>; }
function LifecycleAction({ state, ready, fundingReady, pending, onMove }: { state: string; ready: boolean; fundingReady: boolean; pending: boolean; onMove: (state: string) => void }) { const next: Record<string, [string, string]> = { shaping: ["inviting", "Invite the people"], inviting: ["awaiting_responses", "Wait for responses"], awaiting_responses: ["aligned", "Mark the room aligned"], aligned: ["funding", "Open funding"], funding: ["funded", "Confirm secured Gems"], funded: ["live", "Bring it live"], live: ["completed", "Complete the Moment"], completed: ["reviewed", ACTIVATION_RETURN_REVIEW.reviewedCta] }; const action = next[state]; if (!action) return <div className="mt-6 rounded-2xl bg-primary p-4 text-black"><Rocket className="h-5 w-5" /><p className="mt-3 font-black">The activation is {state}.</p></div>; const blocked = pending || (state === "shaping" && !ready) || (state === "funding" && !fundingReady); return <><Button disabled={blocked} onClick={() => onMove(action[0])} className="mt-6 w-full bg-primary font-black text-black"><Rocket className="mr-2 h-4 w-4" />{action[1]}</Button>{state === "funding" && !fundingReady && <p className="mt-2 text-center text-[9px] leading-4 text-white/35">Secured Gems must meet the requested amount before this becomes funded.</p>}</>; }
